/**
 * Built-in brand icons (simple-icons, bundled; never fetched). A merchant's
 * text (K* dropped) is tested against the patterns in order, the first hit
 * wins, so sub-brands come before their parent ('GOOGLE *YouTubePremium' is
 * YouTube, not Google). Each slug is checked against the package by a test;
 * the web gets only these icons, generated by scripts/gen-brand-icons.ts.
 *
 * Not in simple-icons (monogram instead): Amazon, Amazon Prime, OpenAI,
 * Circle K, Tele2, Willys, ICA, Rusta, Kjell & Company,
 * Parkster, Swedbank, Bank Norwegian, CSN, Podme.
 * Wrong brand under the same name: 'coop' is the British Co-op, 'norwegian'
 * the airline. Google One has no icon of its own and gets Google's.
 */
export const BRANDS: { slug: string; pattern: RegExp }[] = [
  { slug: "youtube", pattern: /YOUTUBE/i },
  { slug: "googleplay", pattern: /GOOGLE ?\*GOOGLE P|GOOGLE PLAY/i },
  { slug: "googlecloud", pattern: /GOOGLE ?\*? ?CLOUD/i },
  { slug: "google", pattern: /\bGOOGLE\b/i },
  { slug: "apple", pattern: /APPLE\.COM|\bITUNES\b/i },
  { slug: "spotify", pattern: /SPOTIFY/i },
  { slug: "plex", pattern: /PLEXINC|\bPLEX\b/i },
  { slug: "claude", pattern: /CLAUDE/i },
  { slug: "anthropic", pattern: /ANTHROPIC/i },
  { slug: "netflix", pattern: /NETFLIX/i },
  { slug: "lidl", pattern: /LIDL/i },
  { slug: "steam", pattern: /^STEAM\b|STEAMGAMES|STEAMPOWERED/i },
  { slug: "ikea", pattern: /\bIKEA\b/i },
  { slug: "trakt", pattern: /\bTRAKT\b/i },
];

export const BRAND_SLUGS = BRANDS.map((b) => b.slug);

/** Payment intermediaries: the real merchant follows their '*' ('PAYPAL *STEAM'). Same list as the web's monogram.ts. */
const MERCHANT_AFTER_STAR = /^(?:PAYPAL|KLARNA|I?ZETTLE_?|SUMUP)\s*\*\s*(.+)$/i;

/** The built-in brand for a merchant text, if any; behind a payment intermediary, the merchant's. */
export function brandFor(text: string): string | null {
  const t = text.replace(/^K\*\s*/i, "");
  const merchant = MERCHANT_AFTER_STAR.exec(t)?.[1];
  const find = (s: string) => BRANDS.find((b) => b.pattern.test(s))?.slug ?? null;
  return (merchant && find(merchant)) || find(t);
}
